     4→import { Lexer } from "./lexer";
     5→import { Parser } from "./parser";
     6→import { TypeChecker } from "./checker";
     7→
     8→function lex(source: string) {
     9→  const lexer = new Lexer(source);
    10→  return lexer.tokenize();
    11→}
    12→
    13→function parse(source: string) {
    14→  const { tokens, errors: lexErrors } = lex(source);
    15→  if (lexErrors.length > 0) throw new Error(`Lex error: ${lexErrors[0].message}`);
    16→  const parser = new Parser(tokens);
    17→  const { program, errors: parseErrors } = parser.parse();
    18→  if (parseErrors.length > 0) throw new Error(`Parse error: ${parseErrors[0].message}`);
    19→  return program;
    20→}
    21→
    22→function check(source: string) {
    23→  const program = parse(source);
    24→  const checker = new TypeChecker();
    25→  const errors = checker.check(program);
    26→  if (errors.length > 0) throw new Error(`Check error: ${errors[0].message}`);
    27→  return program;
    28→}
