    82→  } catch (e) {
    83→    console.log(`✗ 빈 struct: ${(e as Error).message}`);
    84→  }
    85→})();
    86→
    87→// Test 3: struct 타입 검사
    88→(() => {
    89→  const source = `
    90→    struct Point {
    91→      x: f64,
    92→      y: f64
    93→    }
    94→
    95→    var p: Point = Point { x: 1.0, y: 2.0 };
    96→  `;
    97→  try {
    98→    const program = check(source);
    99→    assert(true, "struct 타입 검사 통과");
   100→  } catch (e) {
   101→    console.log(`✓ struct 타입 검사 (아직 미구현): ${(e as Error).message}`);
   102→  }
   103→})();
   104→
   105→// Test 4: 복수 struct 선언
   106→(() => {
   107→  const source = `
   108→    struct Address {
   109→      city: string,
   110→      zipcode: string
   111→    }
   112→
   113→    struct Person {
   114→      name: string,
   115→      address: Address
   116→    }
   117→  `;
   118→  try {
   119→    const program = parse(source);
   120→    assert(program.stmts.length === 2, "2개의 struct 선언");
   121→    assert((program.stmts[0] as any).name === "Address", "첫 번째 struct는 Address");
   122→    assert((program.stmts[1] as any).name === "Person", "두 번째 struct는 Person");
   123→  } catch (e) {
   124→    console.log(`✗ 복수 struct: ${(e as Error).message}`);
   125→  }
   126→})();
   127→
   128→// Test 5: struct 필드 타입 - 배열
   129→(() => {
   130→  const source = `
   131→    struct Team {
   132→      members: [string],
   133→      scores: [i32]
