          city: string,
          zipcode: string
        }

        struct Person {
          name: string,
          address: Address
        }
      `;
      const program = parse(source);
      expect(program.stmts.length).toBe(2);
      expect((program.stmts[0] as any).name).toBe("Address");
      expect((program.stmts[1] as any).name).toBe("Person");
    });
  });

  describe("struct 필드 타입 - 배열", () => {
    it("배열 필드 파싱", () => {
      const source = `
        struct Team {
          members: [string],
          scores: [i32]
        }
