      const { tokens } = lex(source);
      const hasFor = tokens.some((t) => t.type === "FOR");
      const hasOf = tokens.some((t) => t.type === "OF");
      expect(hasFor).toBe(true);
      expect(hasOf).toBe(true);
    });
  });

