  describe("for...of 루프 변수 수정", () => {
    it("루프 변수 할당 시도", () => {
      const source = `
        for x of [1, 2, 3] {
          x = 10;
        }
      `;
      try {
        const program = check(source);
        // 미지원일 수 있음
