          var y = x;
        }
        var z: i32 = x;
      `;
      const program = check(source);
      expect(program.stmts.length).toBe(4);
    });
  });

  describe("for...of 배열 타입 다양성", () => {
    it("f64 배열 순회", () => {
      const source = `
        for x of [1.0, 2.0, 3.0] {
          var y: f64 = x;
        }
      `;
      const program = check(source);
      expect(program.stmts.length).toBe(1);
    });
  });

  describe("for...of 배열 변수 순회", () => {
    it("변수 이터러블", () => {
      const source = `
        var arr: [i32] = [1, 2, 3];
        for x of arr {
          var y: i32 = x;
        }
      `;
      const program = check(source);
      expect(program.stmts.length).toBe(2);
    });
  });

  describe("for...of 루프 본체 다중 문", () => {
    it("복합 루프 본체", () => {
      const source = `
        for x of [1, 2, 3] {
          var y = x;
          var z = y;
          var w = z;
        }
      `;
      const program = parse(source);
      const forOfStmt = program.stmts[0] as any;
      expect(forOfStmt.body.length).toBe(3);
    });
  });

  describe("for...of 문자열 리터럴", () => {
    it("문자열 순회", () => {
      const source = `
        for ch of "abc" {
          var s: string = ch;
        }
      `;
      const program = check(source);
      expect(program.stmts.length).toBe(1);
    });
  });

  describe("for...of 루프 변수 수정", () => {
    it("루프 변수 할당 시도", () => {
      const source = `
        for x of [1, 2, 3] {
          x = 10;
        }
      `;
      try {
        const program = check(source);
        // 미지원일 수 있음
        expect(program.stmts.length).toBe(1);
      } catch {
        // immutable 위반 감지
        expect(true).toBe(true);
      }
    });
  });

  describe("for...of boolean 배열", () => {
    it("bool 타입 배열", () => {
      const source = `
        for b of [true, false] {
          var x: bool = b;
        }
      `;
      const program = check(source);
      expect(program.stmts.length).toBe(1);
    });
  });

  describe("for...of 빈 배열", () => {
    it("공배열 순회", () => {
      const source = `
        for x of [] {
          var y = x;
        }
      `;
      const program = check(source);
      expect(program.stmts.length).toBe(1);
    });
  });
});

