      expect(inner.kind).toBe("while_stmt");
    });
  });

  describe("while 루프 조건식", () => {
    it("조건식 타입 검사", () => {
      const source = `
        var x = 0;
        while x < 10 {
          x = x + 1;
          if x == 5 {
            break;
          }
        }
      `;
      const program = check(source);
      expect(program.stmts.length).toBe(2);
    });
  });

  describe("while 조건 변수 접근", () => {
    it("변수 기반 조건", () => {
      const source = `
        var done = false;
