      expect(program.stmts.length).toBe(2);
    });
  });

  describe("while 조건 변수 접근", () => {
    it("변수 기반 조건", () => {
      const source = `
        var done = false;
        while !done {
          var x = 1;
        }
      `;
      const program = check(source);
      expect(program.stmts.length).toBe(2);
    });
  });

  describe("break와 continue 혼합", () => {
    it("조건부 제어흐름", () => {
      const source = `
        while true {
          if false {
            break;
          } else {
            continue;
          }
        }
      `;
      const program = parse(source);
      expect(program.stmts.length).toBe(1);
    });
  });
});

